/*	Renders the page a coordinator reaches from the staffing complete email.
	Read only - publishing happens on the POST in the publish handler.
	Role names and the verb both come from config, never hardcoded	*/

const cfg = $('Config').first().json;
const link = $('Extract link').first().json;
const event = ($json.data || {}).node || null;

const staffList = (((event || {}).staff || {}).edges || []).map(e => e.node);
const coordRole = String(cfg.COORDINATOR_ROLE_NAME).trim();
const me = staffList.find(s => s.contact && s.contact.id === link.contactId) || null;
const isCoordinator = me !== null && String((me.staffRole || {}).name || '').trim() === coordRole;

/*	The verb for what an instructor does with an event. Both forms are used on this page:
	short of people to deliver it, and Delivering this event. The literals are a last resort if
	config is blank, not the setting - change VERB_BASE and VERB_GERUND in Config	*/
const verb = String(cfg.VERB_BASE || 'deliver').trim();
const verbing = String(cfg.VERB_GERUND || 'delivering').trim();
const titleCase = (s) => s.charAt(0).toUpperCase() + s.slice(1);

const esc = (v) => String(v === null || v === undefined ? '' : v)
	.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;');

const prettyDate = (iso) => {
	if (!iso) { return ''; }
	const d = new Date(String(iso).replace(' ', 'T'));
	if (isNaN(d.getTime())) { return String(iso); }
	const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
	return months[d.getMonth()] + ' ' + d.getDate() + ', ' + d.getFullYear();
};

const page = (title, body) => '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>' + esc(title) + '</title><style>' + cfg.BRAND_CSS + '</style></head><body><header class="masthead"><p>' + esc(cfg.BRAND_NAME) + '</p></header><main>' + body + '</main></body></html>';

if (!event) {
	return [{ json: { html: page('We could not open this event', '<h1>We could not open this event</h1><div class="notice error"><p>The link may be incomplete, or the event may no longer exist.</p></div><p>Please reply to the email you came from and someone will help.</p>') } }];
}

/*	Publishing changes visibility, so only the coordinator may do it	*/
if (!isCoordinator) {
	return [{ json: { html: page('Only the ' + coordRole + ' can publish', '<h1>Only the ' + esc(coordRole) + ' can publish this event</h1><div class="notice error"><p>Publishing is done by the ' + esc(coordRole) + ' named on the event.</p></div><p>If you think that should be you, reply to the email you came from and someone will sort it out.</p>') } }];
}

const header = '<h1>' + esc(event.title) + '</h1><p class="meta"><span>' + esc(prettyDate(event.classroomStart)) + '</span>'
	+ (event.location ? ' &middot; <span>' + esc(event.location.name) + '</span>' : '') + '</p>';

/*	Already published - say so rather than offering to do it again. Nothing is wrong
	here, so it closes off calmly rather than reading as an error	*/
if (String(event.lifecycleState || '') !== 'draft') {
	return [{ json: { html: page('Already published', header + '<div class="notice"><p>This event is already <strong>' + esc(event.lifecycleState) + '</strong>. Nothing further to do here.</p></div><p>You can close this page.</p>') } }];
}

/*	Per role: required against confirmed. Anyone assigned in that role counts as confirmed,
	because a decline removes them from the event. The coordinator is shown but not counted,
	since they are set by hand and never answer an invitation	*/
const required = event.requiredStaff || [];
const roleRows = [];
let totalRequired = 0;
let totalConfirmed = 0;

for (const req of required) {
	const roleName = String((req.staffRole || {}).name || '').trim();
	const qty = Number(req.quantity || 0);
	if (qty === 0) { continue; }
	const held = staffList.filter(s => String((s.staffRole || {}).name || '').trim() === roleName).length;
	roleRows.push(Math.min(held, qty) + ' of ' + qty + ' ' + roleName);
	if (roleName === coordRole) { continue; }
	totalRequired = totalRequired + qty;
	totalConfirmed = totalConfirmed + Math.min(held, qty);
}

const complete = totalRequired > 0 && totalConfirmed >= totalRequired;
const onEvent = staffList.filter(s => String((s.staffRole || {}).name || '').trim() !== coordRole);

const people = onEvent.length
	? '<ul class="people">' + onEvent.map(s => '<li><span>' + esc(s.contact.firstName + ' ' + s.contact.lastName) + '</span><span class="role">' + esc(String((s.staffRole || {}).name || '').trim()) + '</span></li>').join('') + '</ul>'
	: '<p><em>Nobody is currently assigned to ' + esc(verb) + ' this event.</em></p>';

const status = totalRequired === 0
	? '<div class="notice warn"><p>No required personnel are set on this event, so there is nothing to check staffing against. Publish only if you are sure.</p></div>'
	: (complete
		? '<div class="notice"><p><strong>Staffing is complete.</strong> ' + esc(roleRows.join(', ')) + '.</p></div>'
		: '<div class="notice warn"><p><strong>Staffing is not complete.</strong> ' + esc(roleRows.join(', ')) + '. You can still publish, but the event will go live short of people to ' + esc(verb) + ' it.</p></div>');

const body = header + status
	+ '<h2>' + esc(titleCase(verbing)) + ' this event</h2>' + people
	+ '<form method="post" action="' + esc(cfg.PUBLISH_SUBMIT_URL) + '">'
	+ '<input type="hidden" name="e" value="' + esc(link.eventId) + '">'
	+ '<input type="hidden" name="c" value="' + esc(link.contactId) + '">'
	+ '<input type="hidden" name="t" value="' + esc(link.linkToken) + '">'
	+ '<div class="check"><input type="checkbox" id="notify" name="notify" value="yes" checked>'
	+ '<label for="notify">Tell everybody ' + esc(verbing) + ' it<span class="hint">Sends each of them a note that the event is going ahead. Untick if you would rather tell them yourself.</span></label></div>'
	+ '<p><button type="submit">Publish this event</button></p></form>';

return [{ json: { html: page('Publish event', body) } }];

/*	The publish link in the staffing complete email carries a random token saved per event
	by 40 Response Handler. A newer completion email replaces it, so older links expire.
	Nothing is shown about the event without a matching token. Nothing is written here	*/

const cfg = $('Config').first().json;
const link = $('Extract link').first().json;
const rows = $input.all().map((item) => item.json).filter((row) => row && row.event_id);
const row = rows.find((r) => String(r.event_id) === String(link.eventId)) || null;

/*	Compares in constant time, so response timing does not leak how much of a guess
	was right. An empty token never matches	*/
const sameToken = (expected, given) => {
	const a = String(expected || '');
	const b = String(given || '');
	if (a === '' || b === '' || a.length !== b.length) { return false; }
	let diff = 0;
	for (let i = 0; i < a.length; i++) { diff = diff | (a.charCodeAt(i) ^ b.charCodeAt(i)); }
	return diff === 0;
};

const esc = (v) => String(v === null || v === undefined ? '' : v)
	.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;');

const page = (title, body) => '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>' + esc(title) + '</title><style>' + cfg.BRAND_CSS + '</style></head><body><header class="masthead"><p>' + esc(cfg.BRAND_NAME) + '</p></header><main>' + body + '</main></body></html>';

const valid = String(link.eventId || '') !== '' && String(link.contactId || '') !== '' && row !== null && sameToken(row.token, link.linkToken);
const heading = 'This link is invalid or has expired';

return [{ json: {
	valid: valid,
	html: valid ? '' : page(heading, '<h1>' + esc(heading) + '</h1><div class="notice error"><p>' + 'This publish link is not valid any more. A newer staffing complete email may have replaced it.' + '</p></div><p>Use the link in the most recent staffing complete email, or publish the event in Administrate.</p>')
} }];
